package com.numbers;

public class Number7 {
//wap to print the all odd numbers in one column and all the even number in second column2
	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int n =10;
		for(int i=1;i<=n;i++) {
			if(i%2!=0) {
				System.out.println(i+ " " +(i+1));
			}
		}

	}

}
